Approach: the registry is a dictionary of `Tool` descriptors. `call` is a straight-line pipeline of cheap checks ordered so each failure reveals as little as possible: name, scope, shape, approval, execution. Strict models (`extra="forbid"`) are enforced at registration time, so a forgotten setting fails at startup rather than in production.

**`toolgate.py`**

```python
from __future__ import annotations

import logging
from collections.abc import Callable
from dataclasses import dataclass
from typing import Literal

from pydantic import BaseModel, ValidationError

log = logging.getLogger(__name__)

Status = Literal["ok", "invalid_arguments", "unknown_tool", "forbidden", "needs_approval", "error"]


@dataclass(frozen=True, slots=True)
class Ctx:
    """Authenticated identity. Built by the server, never parsed from model output."""
    tenant_id: str
    scopes: frozenset[str]


@dataclass(frozen=True, slots=True)
class Observation:
    status: Status
    content: str


@dataclass(frozen=True, slots=True)
class Tool:
    name: str
    description: str
    args_model: type[BaseModel]
    handler: Callable[[BaseModel, Ctx], str]
    scope: str
    needs_approval: bool = False


class ToolRegistry:
    def __init__(self) -> None:
        self._tools: dict[str, Tool] = {}

    def register(self, tool: Tool) -> None:
        if tool.name in self._tools:
            raise ValueError(f"duplicate tool {tool.name!r}")
        if tool.args_model.model_config.get("extra") != "forbid":
            raise ValueError(f"{tool.name}: args model must set extra='forbid'")
        self._tools[tool.name] = tool

    def definitions(self) -> list[dict]:
        return [
            {"type": "function",
             "function": {"name": t.name, "description": t.description,
                          "parameters": t.args_model.model_json_schema()}}
            for t in self._tools.values()
        ]

    def call(self, name: str, arguments: str, ctx: Ctx, *, approved: bool = False) -> Observation:
        tool = self._tools.get(name)
        if tool is None:
            return Observation("unknown_tool",
                               f"unknown tool {name!r}; available: {', '.join(sorted(self._tools))}")
        if tool.scope not in ctx.scopes:
            return Observation("forbidden", f"tool {name!r} is not permitted for this session")
        try:
            args = tool.args_model.model_validate_json(arguments)
        except ValidationError as exc:
            problems = [f"{'.'.join(map(str, e['loc'])) or '<root>'}: {e['msg']}"
                        for e in exc.errors(include_url=False)[:3]]
            return Observation("invalid_arguments", "; ".join(problems))
        if tool.needs_approval and not approved:
            return Observation("needs_approval", f"{name} requires human approval")
        try:
            return Observation("ok", tool.handler(args, ctx))
        except Exception:                                   # noqa: BLE001 - boundary
            log.exception("tool %s failed", name)
            return Observation("error", f"tool {name!r} failed")
```

**`test_toolgate.py`**

```python
import pytest
from pydantic import BaseModel, ConfigDict, Field

from toolgate import Ctx, Tool, ToolRegistry


class SearchArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")
    query: str = Field(min_length=1, max_length=100)
    limit: int = Field(5, ge=1, le=20)


class CancelArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")
    order_id: str = Field(pattern=r"^ord_[a-z0-9]{8}$")


class LooseArgs(BaseModel):
    x: int


calls: list[str] = []


def search(args: SearchArgs, ctx: Ctx) -> str:
    calls.append("search")
    return f"[{ctx.tenant_id}] results for {args.query!r} (limit {args.limit})"


def cancel(args: CancelArgs, ctx: Ctx) -> str:
    calls.append("cancel")
    return f"cancelled {args.order_id}"


def boom(args: SearchArgs, ctx: Ctx) -> str:
    raise RuntimeError("db password is hunter2")


@pytest.fixture
def registry():
    calls.clear()
    reg = ToolRegistry()
    reg.register(Tool("search_orders", "Search orders.", SearchArgs, search, "orders:read"))
    reg.register(Tool("cancel_order", "Cancel an order.", CancelArgs, cancel,
                      "orders:write", needs_approval=True))
    reg.register(Tool("flaky", "Always fails.", SearchArgs, boom, "orders:read"))
    return reg


READER = Ctx("t1", frozenset({"orders:read"}))
WRITER = Ctx("t1", frozenset({"orders:read", "orders:write"}))


def test_definitions_are_generated_from_models(registry):
    defs = {d["function"]["name"]: d["function"] for d in registry.definitions()}
    assert set(defs) == {"search_orders", "cancel_order", "flaky"}
    assert defs["search_orders"]["parameters"]["required"] == ["query"]
    assert defs["cancel_order"]["parameters"]["additionalProperties"] is False


def test_ok_path_uses_session_tenant(registry):
    obs = registry.call("search_orders", '{"query": "shoes"}', READER)
    assert obs.status == "ok" and obs.content == "[t1] results for 'shoes' (limit 5)"


def test_unknown_tool_lists_available_names(registry):
    obs = registry.call("drop_tables", "{}", WRITER)
    assert obs.status == "unknown_tool"
    assert "cancel_order, flaky, search_orders" in obs.content


def test_scope_is_checked_before_arguments_are_parsed(registry):
    obs = registry.call("cancel_order", "not even json", READER)
    assert obs.status == "forbidden"
    assert "json" not in obs.content.lower()


@pytest.mark.parametrize("arguments", [
    '{"query": ""}',
    '{"query": "ok", "limit": 99}',
    '{"query": "ok", "tenant_id": "t2"}',
    "[]",
    "not json",
])
def test_bad_arguments_never_reach_the_handler(registry, arguments):
    obs = registry.call("search_orders", arguments, READER)
    assert obs.status == "invalid_arguments"
    assert calls == []


def test_error_summary_is_capped_at_three_problems(registry):
    obs = registry.call("search_orders", '{"query": "", "limit": 0, "a": 1, "b": 2, "c": 3}', READER)
    assert obs.content.count(";") <= 2


def test_destructive_tool_needs_approval_and_runs_once_approved(registry):
    first = registry.call("cancel_order", '{"order_id": "ord_ab12cd34"}', WRITER)
    assert first.status == "needs_approval" and calls == []
    second = registry.call("cancel_order", '{"order_id": "ord_ab12cd34"}', WRITER, approved=True)
    assert second.status == "ok" and calls == ["cancel"]


def test_handler_exceptions_do_not_leak_details(registry):
    obs = registry.call("flaky", '{"query": "x"}', READER)
    assert obs.status == "error"
    assert "hunter2" not in obs.content


def test_registration_rules(registry):
    with pytest.raises(ValueError):
        registry.register(Tool("search_orders", "dup", SearchArgs, search, "orders:read"))
    with pytest.raises(ValueError):
        registry.register(Tool("loose", "no forbid", LooseArgs, search, "orders:read"))
```

